k1 = instance/num_inst;
k2 = k1 + trel - int(k1+trel);

y0 = k2+.01 ;

xwidth = .1*(cos(6*k1)+3); //breite
xofs = .1*cos(k2*6+trel)*y0;
x = .5 + .4*xwidth*(.2+y0)*sin(k1*1383*xwidth) + xofs;
//xwidth in der letzten Klammer : Test

y = y0;

bright = 1-sqr(y0); 
a = max(bright,0)*.4; a2 = 0;
rad = .4*y0+.1 - .0*sin(k1*954);

r = .0; g = 0; b = .0;
r2 = 0; g2 = 0; b2= .3; //## rot mit ampl. mod !
additive = 1; ///sonst andere farben im warp-s gestoert

//q25 = time/4;
//trel = 2* (q25/2-int(q25/2));
trel = q25;
copies = 1;
copy = (instance%copies)/copies;
