k2 = k1 + .5;
trel = trel ;
t0 = .5; //do not change

phase = above(trel,t0);
mov1 = bnot(phase)* (t0-trel + .01*k1);
mov2 = phase * (trel-t0); //####
//mov2 = pow(mov2,.8);
stray = 1.2-phase;

Tht = 3.14*sin(1234.2*k1+time*bnot(phase)) * stray ;
Phi = 3245.1*k1;

size0 = .02;
ox = mov1*q27 + sin(Tht)*cos(phi)* (size0+mov2*(2+k1));
oy = mov1*12 + cos(Tht)* (size0+4*mov2*k2)*(1-mov2*k2)/2;
oz = mov1*8 + sin(Tht)*sin(phi)* (size0+mov2*2*(2+k1));

z0 = 1;
rad = .03 / (oz+z0)/(1+trel*rand(100)/50);

x = .5 + ox/(oz+z0);
y = q29+.2+ oy/(oz+z0);

a = .1*bnot(phase)+phase*max(0,1-mov2*0)*above(oz+z0,0)*.8;

presetParts.warp:
sampler sampler_pw_noise_lq;
sampler sampler_pw_noise_hq;
static const float3 size1 =  float3(.1,.2,.25);
static const float3 posx1 = float3(.1,.275,.88)+.4;
static const float3 posy1 = float3(.064,.3,.5);

static const float3 size2 =  float3(.1,.1,.2);
static const float3 posx2 = float3(.1,-.125,.08);
static const float3 posy2 = float3(.064,.4,.6);
float2 uv1, rs0, rs, uv2, uv3, dz, hor, ver;
float noise, z, dist, cog1, rod1, cog2, trel;

float cog (float3 uvx, float3 uvy, float3 size, float3 rot) {float3 rad1, ang1, wheel; float res;
  uvx = frac(1*uvx)-.5; uvy = frac(1*uvy)-.5;
  rad1 = sqrt(uvx*uvx+uvy*uvy);  ang1 = atan2(uvx,uvy)+rot/size;
  wheel = saturate(100*(size-rad1) - 1.5*clamp(sin(180*ang1*size),-.7,.7));
  wheel -= .25*saturate(sin(rad1*120));
  wheel -= saturate(4*sin(rad1*32+3.5)-2) * saturate(4*sin(8*ang1));;
  wheel = saturate(wheel)*float3(0,1,1); //##

  res = wheel.r + saturate(1-0*wheel.r)*wheel.g;
  res += saturate(1-0*res)*wheel.b;
  return res;}


float rod (float2 uvi) {float3 rad1 ; float res;
    uvi = frac(uvi)-.5; 
    rad1 = saturate (2-64*abs(uvi.x)+exp(-uvi.y*uvi.y*128));
    rad1 -= .2*(uvi.x*uvi.x+uvi.y*uvi.y <= .0004);
    rad1 -= .5*saturate(1.4-uvi.x*uvi.x*2048);
    return saturate(rad1);}


shader_body {
uv1 = (uv-.5);

//Zahnraeder
trel = q1;
cog1 = cog (uv1.x+posx1, uv1.y+posy1, size1, float3 (1,-1,1)*trel + float3(0.012,-0.029,0.0));

rod1 = rod (uv1 + float2(posx1[2],posy1[2]) + size1[2]*.6*float2(cos(trel*4), sin(trel*4)));

trel = q2;
cog2 = cog (uv1.x+posx2, uv1.y+posy2, size2, float3 (1,-1,1)*trel + float3(0.012,-0.029,0.0));

ret.g = cog1 + .8*saturate(1-8*cog1)*cog2;
ret.g = rod1 + .8*saturate(1-8*rod1)*ret.g;
//ret.g = cog2;
//ret.g = cog1;


float copy = tex2D (sampler_fw_main, (uv_orig-.5).yx*2+.25+.0*float2(q5,q6)).g;
ret.g = max(ret.g,copy*.4);


ret.b = GetPixel(uv).b*.5;


}

presetParts.comp:
sampler sampler_pw_noise_lq;
static const float quality =2, depth = q29;
float3 screen3, sun, cog;
float2 dz, uv0, uv1, uv2, uv4, rsk, dz1,tmp2, Kugel1, rsl;
float  m,n,noise,mask, smoke, mask1, gmask,dx,dy,rad1, lprof,dist,flash;
float  mask2;
static float2 hor = float2 (texsize.z,0)*2;
static float2 ver = float2 (0,texsize.w)*2;
static float2 mov = float2 (q5,q6);

static float3 t = float3(q14,q15,q16);
static float3 s = float3(q17,q18,q19);
static float3 ts = -cross(s,t);
static float3 pos = float3 (q11,q12,q13);
float3 lavcol (float t) {return saturate(float3(t,pow(t,2.1),pow(t,6)));}

float2 project (float dist) {  float z;
  z = 4*dist/mul(cross(ts,-t),screen3);
  gmask = (z >= -4) * (z <= 4);
  return float2(mul(float2x3(ts,t),cross(pos,screen3))*z*gmask);}

shader_body {uv0 = uv;
screen3 = float3 ((uv-.5)*aspect.xy,1);//wirkt wie zoom / Tele ###

//********* SMOKE
dist = .25; 
rsl = project (dist)+ mov*.5 ;
smoke = GetPixel(frac(rsl)).b ; //mittelwert null !#

//********* COGWHEELS
dist = .5; 
for (m=1; m <= quality; m++) {
  rsl = project (dist)+ mov ;
  lprof = GetPixel(frac(rsl)).g-.5 ; //mittelwert null !#
  dist -= lprof/quality*depth; 
}
cog = lprof+.5;

mask = saturate(4*cog-smoke*2);// * (rsl.y >= -1) : Oberkante;
mask1 = saturate(8*cog);
dz.x = GetPixel (rsl.xy-hor).g - GetPixel (rsl.xy+hor).g;
dz.y = GetPixel (rsl.xy-ver).g - GetPixel (rsl.xy+ver).g;
sun = saturate(.1/length(sin(rsl*4)+dz*16)) ;
sun *= .5+.5*tex2D (sampler_noise_hq,sun/4+mov/4);
cog = 2*sun*(1+1*cog);
ret = lerp(smoke/2,cog,mask) ;

rsl = project(.5)+float2(q9,q10);
flash = saturate(1+(q8%2)-mask1)*bass/2/sqrt(length(sin(time+q8+4*atan2(rsl.y,rsl.x))));
ret += (.1+smoke)*(q28%3 <= 1)*flash*float3(0,.5,1);
//ret = GetPixel(uv0*aspect.xy+.0);
}

